install(FreeMarker) { templateLoader = ClassTemplateLoader(javaClass.classLoader, "templates") }
routing {
    get("/orders/{id}") {
        val id = call.parameters["id"] ?: return@get call.respond(HttpStatusCode.BadRequest)
        val order = orders.find(id)                   // worker services the request
        call.respond(FreeMarkerContent("orders/show.ftl", mapOf("order" to order)))
    }
}
